def transform(grid):
    R, C = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    # flood fill background from border; unreached bg cells are enclosed -> 4
    seen = [[False]*C for _ in range(R)]
    stack = []
    for r in range(R):
        for c in (0, C-1):
            if grid[r][c] == bg and not seen[r][c]:
                seen[r][c] = True; stack.append((r, c))
    for c in range(C):
        for r in (0, R-1):
            if grid[r][c] == bg and not seen[r][c]:
                seen[r][c] = True; stack.append((r, c))
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr, cc = r+dr, c+dc
            if 0 <= rr < R and 0 <= cc < C and grid[rr][cc] == bg and not seen[rr][cc]:
                seen[rr][cc] = True; stack.append((rr, cc))
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg and not seen[r][c]:
                out[r][c] = 4
    return out
